// Independent PLAY-04 re-check: rerun the Chromium clock test that failed in RUN-20261016-022 (chooser seat 0), unmodified,
// up to 3 attempts. A sampler logs every host calendar step (wall-minus-monotonic shift > 1 s); Playwright's JSON report
// gives each attempt's test start and duration, so each result shows whether a step landed in the test body (3 s margin).
// Then run the Lab worker checks once.
import { spawn } from 'node:child_process';
const offset = () => Date.now() - performance.timeOrigin - performance.now();
const steps = []; let last = offset();
const sampler = setInterval(() => { const now = offset(); if (Math.abs(now - last) > 1000) steps.push({ wallAfter: Date.now(), shiftMs: Math.round(now - last) }); last = now; }, 50);
function run(cmd, args, cwd) {
  return new Promise(resolve => { let out = ''; const c = spawn(cmd, args, { cwd, stdio: ['ignore', 'pipe', 'pipe'] }); c.stdout.on('data', d => { out += d; }); c.on('exit', code => resolve({ code, out })); });
}
function results(node, acc = []) { if (node && typeof node === 'object') { if (Array.isArray(node.results) && node.title === undefined) for (const r of node.results) acc.push(r); for (const v of Object.values(node)) if (typeof v === 'object') results(v, acc); } return acc; }
const attempts = [];
for (let i = 0; i < 3; i++) {
  const pw = await run('pnpm', ['exec', 'playwright', 'test', 'tests/clock-client.spec.ts', '-g', 'chooser seat 0', '--reporter=json'], 'apps/web');
  let report; try { report = JSON.parse(pw.out.slice(pw.out.indexOf('{'))); } catch { report = null; }
  const rs = report ? results(report).filter(r => r.startTime) : [];
  const r = rs[rs.length - 1], start = r ? Date.parse(r.startTime) : NaN, end = start + (r?.duration ?? 0);
  const overlapping = steps.filter(s => s.wallAfter >= start - 3000 && s.wallAfter <= end + 3000).map(s => s.shiftMs);
  attempts.push({ attempt: i + 1, exitCode: pw.code, status: r?.status ?? 'no-report', testDurationMs: r?.duration ?? null, stepsInTestBody: overlapping, error: r?.error?.message?.split('\n')[0] ?? null });
  if (pw.code === 0 && r?.status === 'passed') break;
}
clearInterval(sampler);
const lab = await run('pnpm', ['test:engine-browser'], '.');
const pass = attempts.filter(a => a.status === 'passed'), fail = attempts.filter(a => a.status !== 'passed');
console.log(JSON.stringify({ attempts, passedWithoutStep: pass.filter(a => !a.stepsInTestBody.length).length, failedWithStep: fail.filter(a => a.stepsInTestBody.length).length, failedWithoutStep: fail.filter(a => !a.stepsInTestBody.length).length, labWorkers: { exitCode: lab.code, pass: (lab.out.match(/^PASS .*$/m) || [''])[0], checks: (lab.out.match(/"checks":\[[^\]]*\]/) || [''])[0] } }, null, 1));
if (!pass.length || lab.code !== 0) process.exitCode = 1;
